parameters.jsCode:
// 1. جلب جميع الصفوف من الشيت
const items = $input.all();

// 2. ترتيب جميع المرشحين تنازلياً حسب الـ Score
const sortedCandidates = items.map(item => item.json).sort((a, b) => {
  return Number(b['Overall Score'] || 0) - Number(a['Overall Score'] || 0);
});

// 3. جلب بيانات المرشح الحالي بأمان
const current = $('Basic LLM Chain2').first().json.output || {};
const currentEmail = $('Basic LLM Chain').first().json.output?.email || 'N/A';
const currentPhone = $('Basic LLM Chain').first().json.output?.phone || 'N/A';

const matchedSkills = Array.isArray(current.matched_skills) ? current.matched_skills : [];
const missingSkills = Array.isArray(current.missing_skills) ? current.missing_skills : [];
const currentScore = Number(current.overall_score || 0);

// 4. بناء صفوف جدول الترتيب
let rankingRows = '';
sortedCandidates.forEach((c, index) => {
  const rowScore = Number(c['Overall Score'] || 0);
  const badgeColor = rowScore >= 80 ? '#10B981' : (rowScore >= 60 ? '#F59E0B' : '#EF4444');
  rankingRows += `
    <tr style="border-bottom: 1px solid #E5E7EB;">
      <td style="padding: 12px; font-weight: bold; text-align: center;">#${index + 1}</td>
      <td style="padding: 12px;">${c['Candidate Name'] || 'N/A'}</td>
      <td style="padding: 12px; text-align: center;"><span style="background: ${badgeColor}; color: white; padding: 4px 8px; border-radius: 6px; font-weight: bold;">${rowScore}%</span></td>
      <td style="padding: 12px;">${c['Classification'] || 'N/A'}</td>
      <td style="padding: 12px; color: #DC2626;">${c['Missing Skills'] || 'None'}</td>
    </tr>
  `;
});

// 5. تصميم قالب الإيميل
const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #F3F4F6; margin: 0; padding: 20px; color: #1F2937; }
    .container { max-width: 680px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }
    .header { background: linear-gradient(135deg, #1E40AF, #3B82F6); color: white; padding: 25px; text-align: center; }
    .content { padding: 25px; }
    .card { background: #F9FAFB; border: 1px solid #E5E7EB; border-radius: 8px; padding: 18px; margin-bottom: 25px; }
    .score-badge { font-size: 24px; font-weight: bold; color: ${currentScore >= 80 ? '#10B981' : '#F59E0B'}; }
    table { width: 100%; border-collapse: collapse; margin-top: 15px; font-size: 14px; }
    th { background: #F3F4F6; text-align: left; padding: 10px 12px; font-weight: 600; color: #4B5563; }
    .tag { display: inline-block; background: #EEF2FF; color: #4F46E5; padding: 3px 8px; border-radius: 4px; font-size: 12px; margin: 2px; }
    .missing-tag { display: inline-block; background: #FEE2E2; color: #DC2626; padding: 3px 8px; border-radius: 4px; font-size: 12px; margin: 2px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h2 style="margin:0;">🎯 AI Resume Screening Alert</h2>
      <p style="margin: 5px 0 0 0; opacity: 0.9;">Top Match Candidate Detected</p>
    </div>

    <div class="content">
      <h3 style="color: #111827; border-bottom: 2px solid #E5E7EB; padding-bottom: 8px;">👤 Top Candidate Profile</h3>
      <div class="card">
        <div style="display: flex; justify-content: space-between; align-items: center;">
          <div>
            <h3 style="margin: 0 0 5px 0; color: #1E40AF;">${current.candidate_name || 'N/A'}</h3>
            <p style="margin: 0; font-size: 13px; color: #6B7280;">📧 ${currentEmail} | 📞 ${currentPhone}</p>
          </div>
          <div style="text-align: right;">
            <div class="score-badge">${currentScore}%</div>
            <span style="font-size: 12px; font-weight: 600; color: #4B5563;">${current.classification || 'N/A'}</span>
          </div>
        </div>
        <hr style="border: 0; border-top: 1px solid #E5E7EB; margin: 15px 0;">
        <p style="margin: 5px 0;"><strong>💡 Recommendation:</strong> <span style="font-weight: 600; color: #1E40AF;">${current.recommendation || 'N/A'}</span></p>
        <p style="margin: 5px 0;"><strong>✅ Matched Skills:</strong> ${matchedSkills.length ? matchedSkills.map(s => `<span class="tag">${s}</span>`).join('') : 'None'}</p>
        <p style="margin: 5px 0;"><strong>❌ Missing Skills:</strong> ${missingSkills.length ? missingSkills.map(s => `<span class="missing-tag">${s}</span>`).join('') : '<span style="color:#10B981;">None</span>'}</p>
        <p style="margin: 10px 0 0 0; font-size: 13px; color: #4B5563; line-height: 1.5;"><strong>📝 AI Summary:</strong> ${current.summary_reasoning || 'N/A'}</p>
      </div>

      <h3 style="color: #111827; border-bottom: 2px solid #E5E7EB; padding-bottom: 8px;">🏆 Current Top Candidates Leaderboard</h3>
      <table>
        <thead>
          <tr>
            <th style="text-align: center;">Rank</th>
            <th>Candidate</th>
            <th style="text-align: center;">Score</th>
            <th>Match</th>
            <th>Missing Skills</th>
          </tr>
        </thead>
        <tbody>
          ${rankingRows}
        </tbody>
      </table>
    </div>
  </div>
</body>
</html>
`;

return [{ json: { htmlBody, candidate_name: current.candidate_name, score: currentScore } }];

const candidate = $('Basic LLM Chain2').item.json.output;
const candidateEmail = $('Basic LLM Chain').item.json.output.email;
const jobTitle = $('Basic LLM Chain1').item.json.output.job_title;

let feedbackMessage = '';
if (candidate.overall_score >= 80) {
  feedbackMessage = `🎉 <strong>Great news!</strong> Your profile shows a strong alignment with the <strong>${jobTitle}</strong> position. Our recruiting team will review your application and contact you soon for next steps.`;
} else if (candidate.overall_score >= 60) {
  feedbackMessage = `👍 <strong>Good match!</strong> You have a solid background for the <strong>${jobTitle}</strong> position. Our team is reviewing your profile.`;
} else {
  feedbackMessage = `Thank you for applying for the <strong>${jobTitle}</strong> role. While your background is impressive, we found some skill gaps for this specific opening.`;
}

const candidateHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; background-color: #F8FAFC; margin: 0; padding: 20px; color: #1E293B; }
    .container { max-width: 580px; margin: auto; background: #ffffff; border-radius: 12px; border: 1px solid #E2E8F0; padding: 25px; }
    .header { text-align: center; border-bottom: 1px solid #E2E8F0; padding-bottom: 15px; }
    .score-circle { display: inline-block; width: 65px; height: 65px; line-height: 65px; border-radius: 50%; background: #EEF2FF; color: #4F46E5; font-size: 20px; font-weight: bold; margin: 15px 0; }
    .box { background: #F1F5F9; border-radius: 8px; padding: 15px; margin: 15px 0; font-size: 14px; line-height: 1.5; }
    .tag { display: inline-block; background: #DCFCE7; color: #15803D; padding: 3px 8px; border-radius: 4px; font-size: 12px; font-weight: bold; margin: 2px; }
    .missing-tag { display: inline-block; background: #FEF3C7; color: #B45309; padding: 3px 8px; border-radius: 4px; font-size: 12px; font-weight: bold; margin: 2px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h2 style="margin: 0; color: #0F172A;">Application Received!</h2>
      <p style="margin: 5px 0 0; color: #64748B; font-size: 14px;">Role: <strong>${jobTitle}</strong></p>
    </div>

    <p>Hi <strong>${candidate.candidate_name}</strong>,</p>
    <p>Thank you for submitting your resume! Our AI Screening system has analyzed your profile against the job requirements:</p>

    <div style="text-align: center;">
      <div class="score-circle">${candidate.overall_score}%</div>
      <div style="font-size: 13px; font-weight: bold; color: #4F46E5;">Match Alignment</div>
    </div>

    <div class="box">
      ${feedbackMessage}
    </div>

    <h4 style="margin: 15px 0 6px 0;">🌟 Your Matched Skills:</h4>
    <div>${candidate.matched_skills.map(s => `<span class="tag">✓ ${s}</span>`).join('')}</div>

    ${candidate.missing_skills.length > 0 ? `
    <h4 style="margin: 15px 0 6px 0;">💡 Recommended Skills to Boost:</h4>
    <div>${candidate.missing_skills.map(s => `<span class="missing-tag">⚡ ${s}</span>`).join('')}</div>
    ` : ''}

    <p style="margin-top: 20px; font-size: 12px; color: #94A3B8; border-top: 1px solid #E2E8F0; padding-top: 10px;">
      Best regards,<br>Talent Acquisition Team
    </p>
  </div>
</body>
</html>
`;

return [{
  json: {
    candidateEmail,
    candidateName: candidate.candidate_name,
    jobTitle,
    candidateHtml
  }
}];

const items = $input.all();

// ترتيب المتقدمين من الأعلى تقييماً إلى الأقل
const sortedCandidates = items.map(item => item.json).sort((a, b) => {
  return Number(b['Overall Score'] || 0) - Number(a['Overall Score'] || 0);
});

let rankingRows = '';
sortedCandidates.forEach((c, index) => {
  const score = Number(c['Overall Score'] || 0);
  const badgeColor = score >= 80 ? '#10B981' : (score >= 60 ? '#F59E0B' : '#EF4444');

  rankingRows += `
    <tr style="border-bottom: 1px solid #E2E8F0;">
      <td style="padding: 12px; font-weight: bold; text-align: center;">#${index + 1}</td>
      <td style="padding: 12px; font-weight: 600; color: #0F172A;">${c['Candidate Name'] || 'N/A'}</td>
      <td style="padding: 12px; text-align: center;"><span style="background: ${badgeColor}; color: white; padding: 4px 10px; border-radius: 6px; font-weight: bold; font-size: 13px;">${score}%</span></td>
      <td style="padding: 12px; color: #334155;">${c['Classification'] || 'N/A'}</td>
      <td style="padding: 12px; color: #64748B; font-size: 13px;">${c['Email'] || 'N/A'}</td>
      <td style="padding: 12px; color: #DC2626; font-size: 13px;">${c['Missing Skills'] || 'None'}</td>
    </tr>
  `;
});

const digestHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; background-color: #F8FAFC; margin: 0; padding: 25px; color: #1E293B; }
    .container { max-width: 750px; margin: auto; background: #FFFFFF; border-radius: 12px; border: 1px solid #E2E8F0; padding: 25px; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }
    .header { text-align: center; border-bottom: 2px solid #F1F5F9; padding-bottom: 20px; margin-bottom: 20px; }
    table { width: 100%; border-collapse: collapse; margin-top: 15px; }
    th { background: #F1F5F9; text-align: left; padding: 12px; font-size: 13px; color: #475569; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h2 style="margin: 0; color: #0F172A;">📊 Daily Recruitment Digest</h2>
      <p style="margin: 6px 0 0; color: #64748B; font-size: 14px;">Ranked Leaderboard of all candidate submissions</p>
    </div>

    <table>
      <thead>
        <tr>
          <th style="text-align: center;">Rank</th>
          <th>Candidate</th>
          <th style="text-align: center;">Score</th>
          <th>Match Tier</th>
          <th>Email</th>
          <th>Missing Skills</th>
        </tr>
      </thead>
      <tbody>
        ${rankingRows}
      </tbody>
    </table>

    <p style="margin-top: 25px; font-size: 12px; color: #94A3B8; text-align: center; border-top: 1px solid #E2E8F0; padding-top: 15px;">
      Generated automatically by AI Recruitment Engine • All candidates logged in Google Sheets
    </p>
  </div>
</body>
</html>
`;

return [{ json: { digestHtml, totalCandidates: sortedCandidates.length } }];
